/bin/bash -lc "python3 - <<'PY'
import generate, numpy as np
for i in range(20):
 c=generate.plate_position(i)
 # repeat wrist
 lp=(52,58);rp=(212,49)
 if i<=2: lw=generate.mix(lp,(c[0]-19,c[1]),i/2)
 elif i<=10:lw=(c[0]-19,c[1])
 else:lw=generate.mix((121,45),lp,(i-10)/6)
 if i<=6:rw=rp
 elif i<=9:rw=generate.mix(rp,(c[0]+19,c[1]),(i-6)/3)
 elif i<=17:rw=(c[0]+19,c[1])
 else:rw=generate.mix((195,80),rp,(i-17)/2)
 le=generate.ik((18,103),lw,61,56,-1);re=generate.ik((237,104),rw,58,50,1)
 print(i,'plate',tuple(round(x,1) for x in c),'Lw/e',lw,np.round(le,1),'Rw/e',rw,np.round(re,1))
PY"
